import { showModal } from '@ui-kit/Modal';
import { IPohModalProps } from '@ui-kit/Modal/Modal';

import PreviewEquipModal, { IPreviewEquipModalProps } from './PreviewEquipModal';

export function previewEquipModal(
  { name, weight, value, photo }: IPreviewEquipModalProps,
  modalProps: Partial<IPohModalProps> = {},
) {
  showModal({
    ...modalProps,
    children: () => <PreviewEquipModal name={name} weight={weight} value={value} photo={photo} />,
  });
}

export default { previewEquipModal };
