import PohImagePlaceholder from '@ui-kit/ImagePlaceholder';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

export interface IPreviewEquipModalProps {
  name: string;
  weight: number;
  value: number;
  photo: string;
}

const PreviewEquipModal = ({ name, weight, value, photo }: IPreviewEquipModalProps) => (
  <PohContainer>
    <PohRow>
      <PohCol sm={12} className="d-flex align-items-center justify-content-center flex-wrap py-3">
        <PohImagePlaceholder style={{ maxWidth: '255px' }} src={photo} alt={name} />
        <div className="mt-2">
          <h3 className="text-center">{name}</h3>
          <h5 className="text-center">
            {weight}&thinsp;г. / {value}&thinsp;л.
          </h5>
        </div>
      </PohCol>
    </PohRow>
  </PohContainer>
);

export default PreviewEquipModal;
